    int ny = ay + 48; text("CLANS", x + 22, ny - 4, 13, WOOD); ny += 18; int cnt = 0; for (auto& kv : g.nations) { Nation& n = kv.second; if (!n.met || n.status == "home") continue; ring(x + 22, ny, W - 44, 46, 1, INK); frect(x + 22, ny, W - 44, 46, 0xFFfff7e2); frect(x + 26, ny + 6, 12, 34, HEX(n.color)); text(n.name, x + 48, ny + 3, 18, INK); text(cap(n.status) + " - " + n.temper + " - ruler " + n.ruler, x + 48, ny + 26, 14, 0xFF7a6458); ring(x + W - 250, ny + 16, 200, 10, 1, INK); frect(x + W - 250, ny + 16, 200, 10, PAPER3); frect(x + W - 250, ny + 16, (int)(2 * n.rel), 10, n.rel > 60 ? GREEN : n.rel > 30 ? GOLD : RED); ny += 52; if (++cnt > 6) break; }
