  static void drawJournal(Game& g) { int W = 560, H = 580, x = (winW - W) / 2, y = (winH - H) / 2; panel(x, y, W, H); panelHeader("Journal", "J to close", x + 22, y + 14, W); int ty = y + 62; for (int i = 0; i < NGOALS; i++) { bool done = i < g.goal; bool cur = i == g.goal; if (ty > y + H - 40) break; frect(x + 22, ty + 3, 16, 16, done ? GREEN : cur ? GOLD : PAPER3); ring(x + 22, ty + 3, 16, 16, 1, INK); if (done) text("v", x + 24, ty, 14, 0xFFffffff); text(GOALS[i].t, x + 48, ty, 16, done ? 0xFF8a7468 : INK); std::string r = "+" + std::to_string(GOALS[i].r); text(r, x + W - 60 - tw(r, 15), ty + 1, 15, 0xFF8a5a14); ty += 24; } closeBtn(g, x, y, W); }
